INSERT INTO public.imphq_swipes (user_id, title, criador, plataforma, formato, mecanismo, nicho, tags, blocks) VALUES
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'A — Segredo Duplo + Marilyn', '@gstalves', 'Instagram', 'Astral/Místico', 'Segredo + escassez', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','astral/místico']::text[], '{"gancho": "Tem um homem escondendo duas coisas de você. E a segunda... você sempre suspeitou.", "participacao_ativa": "Toca no coração antes de continuar.", "narrativa": "O baralho revelou que alguém que já cruzou o seu caminho não consegue te tirar da cabeça. Ele estava em outro relacionamento — mas nunca te esqueceu. Existe um laço muito forte entre vocês, porque ele compartilha a mesma frequência que você. Isso é o que chamamos de alma gêmea. Mês passado, uma das escolhidas foi a Marilyn. Ela descobriu que a alma gêmea dela era o próprio vizinho. Em 5 dias, ele a abordou. No dia seguinte, pediu ela em um encontro.", "reframe": "Agora posso mostrar a inicial do nome desse homem — e o rosto dele, desenhado especificamente para você. Mas preciso que você responda 3 perguntas rápidas primeiro.", "cta_engajamento": "Manda esse vídeo para alguém agora. Não escolhe — manda para a primeira pessoa que vier na sua cabeça. Se essa pessoa for um homem, é ele. O universo acabou de te responder.", "cta_venda": "Comenta ALMA aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'B — Rachel + Sarah', '@gstalves', 'Instagram', 'Astral', 'Prova social dupla + choque', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','astral']::text[], '{"gancho": "Tem um homem que quer você — mas algo impede ele toda vez que tenta chegar perto.", "participacao_ativa": "Toca no coração se você já sentiu isso antes.", "narrativa": "Com só 3 perguntas, consigo revelar o que o destino preparou para a sua vida amorosa — e se existe um bloqueio afastando a sua alma gêmea. Isso é o que eu fiz com a Rachel. A leitura apontou exatamente o homem com quem ela está casada há 30 anos. Nome certo. Data em que se conheceram. Mas com a Sarah foi diferente. A leitura revelou que a alma gêmea dela não era o namorado — era o melhor amigo de infância. Hoje estão juntos há 3 anos e noivos.", "reframe": "Não se surpreenda se o teste mostrar que a sua alma gêmea é alguém que você já conhece. E se você ainda não encontrou, eu consigo te dizer quando, onde — e mostrar o rosto dessa pessoa.", "cta_engajamento": "Comenta a inicial do nome dele aqui embaixo. Só a letra. Sem o nome completo. O universo já sabe quem é — você só precisa confirmar.", "cta_venda": "Comenta ELA aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'C — Storytelling Melhor Amiga', '@gstalves', 'Instagram', 'UGC/Storytelling', 'In medias res + prova irrefutável', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','ugc/storytelling']::text[], '{"gancho": "Mostrei o resultado do meu teste para a minha melhor amiga — e ela ficou branca.", "participacao_ativa": "Fica aqui até o final.", "narrativa": "Eu tinha feito esse teste de leitura astral aqui no Instagram, só por curiosidade. Nem levei a sério. Mas quando os resultados saíram, tinha um perfil completo — comportamentos, jeito de agir quando gosta de alguém, características físicas. Parecia uma pessoa real. Aí mostrei pra minha melhor amiga. Ela ficou em silêncio. Depois começou a apontar cada detalhe: ''Isso é meu irmão. É exatamente ele.'' Eu achei que ela estava exagerando — até conhecer o irmão dela de verdade. E aí tudo fez sentido de um jeito que eu não consigo explicar. Estamos juntos há 7 meses. A leitura até mostrou que nossos caminhos tinham se cruzado antes — mas minha frequência ainda não estava alinhada com a dele.", "reframe": "Não era sobre encontrar a pessoa certa. Era sobre alinhar o que estava me impedindo. O teste gerou um desenho do rosto dele — e foi assustadoramente preciso.", "cta_engajamento": "Manda esse vídeo para a sua melhor amiga agora — sem texto, sem explicação. Se ela te perguntar em quem você estava pensando, é porque ela também sentiu. O universo trabalha assim.", "cta_venda": "Comenta ROSTO aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'D — Twin Flame / Retorno', '@gstalves', 'Instagram', 'Astral', 'Saudade + urgência emocional', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','astral']::text[], '{"gancho": "Um homem que te amou no passado vai voltar esse mês para finalmente acertar as coisas.", "participacao_ativa": "Toca no coração se você ainda pensa nele.", "narrativa": "Nesse momento, ele está sozinho olhando fotos antigas de vocês dois. Ele se arrepende de como as coisas terminaram e está procurando uma forma de voltar. Existe um laço muito forte entre vocês — porque ele é o que eu chamo de chama gêmea. Uma conexão 100 vezes mais forte que uma alma gêmea comum. É por isso que seu coração nunca o largou de verdade, mesmo quando sua mente tentou seguir em frente.", "reframe": "Posso mostrar a inicial do nome dele — e o rosto dele, desenhado a partir da sua leitura astral. E também o que está impedindo ele de chegar até você.", "cta_engajamento": "Curte esse vídeo se você ainda pensa nele. Cada curtida é um sinal que você manda — e ele sente, mesmo sem saber de onde vem.", "cta_venda": "Comenta ELE aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'E — Padrão Repetitivo / Frequência', '@gstalves', 'Instagram', 'Transformação', 'Identificação com dor + atalho', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','transformação']::text[], '{"gancho": "Um homem quer você — mas algo sempre atrapalha. E se você olhar bem, já aconteceu mais de uma vez.", "participacao_ativa": "Comenta ''sim'' nos comentários se você se identifica.", "narrativa": "Minha amiga passou 22 anos em um casamento frustrante. Depois ainda teve dois relacionamentos onde o cara começava intenso — e em poucas semanas estava distante, confuso, sumindo. Não tinha nada a ver com os homens. Tinha a ver com a frequência que ela estava emitindo. Completamente desalinhada com a pessoa que ela queria atrair. Quando ela fez esse teste e ajustou a frequência, em 3 semanas manifestou um homem presente, disponível e pronto para um relacionamento de verdade.", "reframe": "Não era esforço. Era um fator invisível que ninguém tinha tocado antes — e que determina quem se conecta com você.", "cta_engajamento": "Comenta SIM aqui embaixo se você reconhece esse padrão na sua vida. Cada comentário é uma intenção — e intenções têm frequência. O universo está contando.", "cta_venda": "Comenta SIM aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'F — Ego vs. Alma', '@gstalves', 'Instagram', 'Educacional', 'Reframe de crença + autoridade', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','educacional']::text[], '{"gancho": "Você continua atraindo homens emocionalmente indisponíveis? Não é azar. É a frequência em que você está travada.", "participacao_ativa": "Toca no coração — você vai querer rever.", "narrativa": "A maioria das pessoas lista características: alto, bonito, engraçado, carinhoso. Isso vem do ego. É o que você acha que quer. A manifestação real vem da alma. Não o que impressiona no papel — o que faz você sentir algo profundo no coração. A sua alma já sabe quem é a sua alma gêmea. Essa pessoa foi escrita no seu mapa astral no momento em que você nasceu. Você só precisa estar na mesma frequência para se encontrar.", "reframe": "Quando a frequência está alinhada, a conexão parece inevitável — como se vocês sempre tivessem se conhecido.", "cta_engajamento": "Salva esse vídeo agora. Toda vez que você abrir de novo, você está se realinhando com a frequência certa. É assim que o universo trabalha — repetição cria atração.", "cta_venda": "Comenta ALMA aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'G — Número Intuitivo', '@gstalves', 'Instagram', 'Participação ativa', 'Comprometimento psicológico', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','participação ativa']::text[], '{"gancho": "Pensa em um número de 1 a 5 agora. Escreve nos comentários.", "participacao_ativa": "Toca no coração também — vou te explicar por que isso importa.", "narrativa": "Esse número não foi por acaso. Ele representa uma pessoa que vai influenciar sua vida mais do que você imagina. Existe uma leitura astral que usa sua data de nascimento para identificar exatamente quem é essa pessoa — a frequência dela, as características, e o rosto desenhado especificamente para você.", "reframe": "Não é um desenho genérico. É uma leitura que usa seu mapa astral para mostrar o rosto de quem o universo escolheu para você.", "cta_engajamento": "Comenta o número que você escolheu aqui embaixo. Quem tiver escolhido o mesmo número que você tem uma conexão de frequência com você. O universo coloca as pessoas certas no mesmo lugar — sempre.", "cta_venda": "Comenta EU aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'H — Dois Homens (Certo vs. Ex)', '@gstalves', 'Instagram', 'Astral', 'Escolha binária + revelação', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','astral']::text[], '{"gancho": "Nesse momento tem dois homens pensando em você. E eu sei qual dos dois é o certo.", "participacao_ativa": "Toca no coração se você já ficou dividida entre dois.", "narrativa": "O primeiro é alguém que te vê com valor. Ele cuida, respeita e já se imagina ao seu lado numa vida real. Se você desse espaço, ele te trataria bem em cada detalhe. O segundo vem do passado. Tem história, memórias, coisas que nunca foram resolvidas. Às vezes você pensa nele — não porque ele é o certo, mas porque esse ciclo nunca foi fechado. As cartas mostram que você sente algo pelos dois — mas também mostram claramente qual deles compartilha a mesma frequência que você.", "reframe": "Posso revelar a inicial dos nomes dos dois — e qual deles realmente merece você. Quem está alinhado com a sua vida e com o amor que você merece ter.", "cta_engajamento": "Comenta 1 se você já sabe qual é o certo. Comenta 2 se ainda está dividida. Não precisa explicar nada — o universo já leu. E os comentários abaixo vão te surpreender.", "cta_venda": "Comenta DOIS aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'I — Emma e Danny (Casamento Errado)', '@gstalves', 'Instagram', 'Storytelling longo', 'Virada dramática + urgência existencial', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','storytelling longo']::text[], '{"gancho": "Ela estava a 3 dias do casamento quando descobriu que estava prestes a casar com a pessoa errada.", "participacao_ativa": "Toca no coração se você já sentiu que algo estava errado mas não sabia explicar.", "narrativa": "Emma veio até mim faltando 3 dias pro casamento. Ela respondeu algumas perguntas simples. Eu analisei a frequência dela, fechei os olhos, e disse algo que a deixou sem chão — que a frequência dela estava completamente desalinhada com a do noivo. E então mostrei a personalidade do homem conectado ao destino dela. A inicial do nome. 30 dias depois, ela conheceu esse homem. Ele se chama Danny. Hoje estão juntos há mais de 20 anos.", "reframe": "Não era sobre o casamento. Era sobre a frequência. Quando ela está desalinhada, você pode estar ao lado de alguém e ainda assim estar sozinha.", "cta_engajamento": "Compartilha esse vídeo agora. Pensa em três pessoas para mandar — mas não manda para nenhuma ainda. A terceira pessoa que veio à sua mente tem algo a te dizer. Observa o que acontece nas próximas 24 horas.", "cta_venda": "Comenta DANNY aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'J — 15.325 Mulheres', '@gstalves', 'Instagram', 'Autoridade + prova social em massa', 'Número específico + urgência', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','autoridade + prova social em massa']::text[], '{"gancho": "Mais de 15 mil mulheres já descobriram quem é a alma gêmea delas com esse teste. Hoje você pode ser a próxima.", "participacao_ativa": "Toca no coração se você quer fazer parte disso.", "narrativa": "Existe uma coisa que separa as mulheres que encontram o amor das que continuam esperando: saber o que está bloqueando essa conexão. Não é sorte. Não é timing. É frequência. Uma delas era Emma. Meses esperando por um sinal de um homem que sentia por ela — mas que continuava se afastando sem explicação. Ela fez o teste. Identificamos o bloqueio. 3 semanas depois, ele mandou mensagem do nada dizendo que não conseguia parar de pensar nela.", "reframe": "Não era ele o problema. Era a frequência dela que estava afastando sem que nenhum dos dois percebesse. Quando isso muda, o tipo de homem que entra na sua vida muda junto.", "cta_engajamento": "Curte esse vídeo agora — cada curtida é uma mulher que está alinhando a frequência junto com você. Quanto mais curtidas, mais forte o campo energético desse vídeo. E você faz parte disso.", "cta_venda": "Comenta AGORA aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'K — Justiça Cósmica / Recompensa', '@gstalves', 'Instagram', 'Validação emocional', 'Reconhecimento da dor + promessa de recompensa', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','validação emocional']::text[], '{"gancho": "Você foi boa com quem não merecia. Deu tudo, se dedicou — e no final foi deixada de lado. O universo viu tudo isso.", "participacao_ativa": "Toca no coração se isso já aconteceu com você.", "narrativa": "Tem mulheres que amam demais as pessoas erradas — não por ingenuidade, mas porque a frequência delas ainda não estava sintonizada com quem realmente merecia receber esse amor. Quando essa frequência muda, as pessoas que chegam mudam. O homem que aparece não some. Não dá migalhas. Não te faz duvidar do que sente. Ele simplesmente está presente — porque ele é feito para a sua frequência.", "reframe": "Existe um teste que revela exatamente onde está esse desalinhamento — e mostra quem é a pessoa feita para você. Inclusive o rosto dela, desenhado a partir da sua leitura astral.", "cta_engajamento": "Comenta MEREÇO aqui embaixo. Não é só uma palavra — é uma declaração de frequência. O universo responde para quem se posiciona. E você merece.", "cta_venda": "Comenta MEREÇO aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'L — O Terceiro Contato', '@gstalves', 'Instagram', 'Participação ativa + ritual', 'Ação imediata + curiosidade', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','participação ativa + ritual']::text[], '{"gancho": "Tem alguém que pensa em você toda hora — e o nome dessa pessoa está no seu celular agora.", "participacao_ativa": "Toca no coração e abre seu WhatsApp. Olha quem é o terceiro contato da sua lista.", "narrativa": "Não foi por acaso que esse nome apareceu. A frequência entre vocês dois está ativa — e essa pessoa está segurando algo que nunca teve coragem de dizer. Existe uma leitura astral que vai além do nome. Ela usa sua data de nascimento para revelar quem é a pessoa destinada a você — as características, o jeito de agir, e até o rosto desenhado especificamente a partir da sua frequência.", "reframe": "Às vezes a alma gêmea já está na sua vida. Só falta o alinhamento certo para o encontro acontecer de verdade.", "cta_engajamento": "Abre seu WhatsApp agora. Olha o terceiro contato da lista. Comenta aqui a primeira letra do nome dessa pessoa. Sem explicação. O universo sabe o que está fazendo.", "cta_venda": "Comenta NOME aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'M — Ele Está Prestes a Sumir', '@gstalves', 'Instagram', 'Urgência de perda', 'Medo de perder + janela de tempo', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','urgência de perda']::text[], '{"gancho": "Tem um homem que pensa em você — mas se você não agir agora, outra mulher vai entrar na vida dele.", "participacao_ativa": "Toca no coração se você sabe exatamente de quem estou falando.", "narrativa": "Ele segura o celular várias vezes querendo te mandar mensagem. Chega a abrir a conversa. E para no último segundo. Não é falta de sentimento. É um bloqueio de frequência — uma barreira invisível que impede essa conexão de se manifestar, mesmo quando os dois sentem que existe algo real entre vocês.", "reframe": "Quando esse bloqueio é identificado e removido, o comportamento dele muda. Sem você fazer nada. Sem mandar mensagem primeiro. Sem forçar.", "cta_engajamento": "Curte esse vídeo agora — antes de fechar. Esse gesto manda um sinal energético para ele. Pode ser exatamente o que falta para ele finalmente agir.", "cta_venda": "Comenta AGIR aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'N — Descrição Física + Timeline Curta', '@gstalves', 'Instagram', 'Imagem mental concreta', 'Especificidade física + promessa próxima', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','imagem mental concreta']::text[], '{"gancho": "Um homem de olhos escuros está prestes a entrar na sua vida — e ao final desse vídeo você já vai saber quem ele é.", "participacao_ativa": "Toca no coração se você está pronta para isso.", "narrativa": "Ele não é alguém distante. Pode ser alguém que você já viu, que já cruzou o seu caminho — mas na hora errada, quando as frequências de vocês ainda não estavam alinhadas. Existe uma leitura astral que usa sua data de nascimento para revelar as características físicas e emocionais da pessoa destinada a você. E mais do que isso — quando e em que circunstância esse encontro vai acontecer.", "reframe": "Não é sobre esperar. É sobre se alinhar. Quando a frequência está certa, o encontro deixa de ser uma possibilidade e vira inevitável.", "cta_engajamento": "Salva esse vídeo. Na próxima vez que você abrir, presta atenção no primeiro rosto que vier à sua mente. Esse é ele.", "cta_venda": "Comenta ELE aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'O — Ele Já Está na Sua Vida', '@gstalves', 'Instagram', 'Revelação próxima', 'Choque de proximidade', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','revelação próxima']::text[], '{"gancho": "A sua alma gêmea já está na sua vida. Você só ainda não sabe quem é.", "participacao_ativa": "Toca no coração se isso te deu arrepios.", "narrativa": "Pode ser alguém do trabalho. Um amigo de longa data. Alguém que você vê toda semana sem perceber o que existe entre vocês. A Rachel descobriu isso na própria leitura — a alma gêmea dela era o homem com quem estava casada há 30 anos. A leitura confirmou o nome, a data em que se conheceram, e as características que ela nunca tinha parado para notar. Com a Sarah foi diferente. Era o melhor amigo de infância. Ela nunca tinha considerado — até o teste revelar o que estava escrito no mapa astral dela desde o nascimento.", "reframe": "O teste não inventa. Ele lê o que já está escrito na sua frequência — e mostra o rosto de quem o universo escolheu para você.", "cta_engajamento": "Comenta aqui a primeira letra do nome de alguém que você conhece e que veio à sua mente agora. Não escolhe — deixa vir. O universo não erra.", "cta_venda": "Comenta PERTO aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'P — Por Que Ele Some', '@gstalves', 'Instagram', 'Diagnóstico emocional', 'Explicação racional de dor irracional', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','diagnóstico emocional']::text[], '{"gancho": "Ele some. Volta. Some de novo. E você fica se perguntando o que fez de errado.", "participacao_ativa": "Toca no coração se você já viveu isso.", "narrativa": "A resposta não está no que você faz ou deixa de fazer. Está na frequência que você está emitindo. Quando a frequência está desalinhada, você atrai homens que começam intensos e somem. Não porque você não é suficiente — mas porque a conexão não tem base energética para se sustentar. Minha amiga passou por dois relacionamentos exatamente assim. Começavam perfeitos. Em poucas semanas, ele estava distante, confuso, sumindo. Quando ela fez o teste e ajustou a frequência, em 3 semanas um homem diferente entrou na vida dela. Presente. Disponível. Sem joguinho.", "reframe": "Quando a frequência muda, o padrão muda. O teste revela onde está o desalinhamento — e mostra quem é a pessoa que está alinhada com você, inclusive o rosto.", "cta_engajamento": "Manda esse vídeo para uma amiga que está passando pela mesma coisa. Se ela te responder ''como você sabia que eu precisava ver isso?'' — é porque o universo está falando com vocês duas ao mesmo tempo.", "cta_venda": "Comenta PADRÃO aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'Q — O Sonho', '@gstalves', 'Instagram', 'Místico/Onírico', 'Experiência universal ressignificada', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','místico/onírico']::text[], '{"gancho": "Se você já sonhou com um rosto que não reconhece — esse é o rosto da sua alma gêmea.", "participacao_ativa": "Toca no coração se isso já aconteceu com você.", "narrativa": "Não é coincidência. Durante o sono, a frequência da sua alma se conecta com a frequência de quem está destinado a você. É por isso que o rosto parece familiar — mesmo sem um nome, mesmo sem uma história. Existe uma leitura astral que usa sua data de nascimento para identificar essa frequência enquanto você está acordada — e gerar um desenho real do rosto dessa pessoa.", "reframe": "Você não precisa esperar pelo próximo sonho. O teste faz essa conexão agora, em menos de 2 minutos, com só 3 perguntas.", "cta_engajamento": "Comenta aqui: você já sonhou com um rosto que não reconhecia? Comenta SIM ou NÃO. Quem tiver comentado SIM — olha os outros comentários. Vocês viram o mesmo rosto.", "cta_venda": "Comenta SONHO aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'R — A Inicial do Nome', '@gstalves', 'Instagram', 'Revelação parcial', 'Curiosidade + âncora concreta', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','revelação parcial']::text[], '{"gancho": "Vou te dizer a inicial do nome da sua alma gêmea. Mas primeiro preciso de uma coisa sua.", "participacao_ativa": "Toca no coração e pensa em alguém que não sai da sua cabeça ultimamente.", "narrativa": "Essa pessoa que veio à sua mente agora — não foi por acaso. A frequência dela está ativa na sua vida nesse momento. Com só sua data de nascimento, consigo identificar a inicial do nome da sua alma gêmea, as características dela, e quando o encontro tem maior probabilidade de acontecer. E mais — o rosto desenhado especificamente a partir da sua leitura astral.", "reframe": "Quando você vê a inicial e reconhece — tudo faz sentido. Não é magia. É frequência. E a sua já está falando.", "cta_engajamento": "Comenta aqui a inicial do nome da pessoa que veio à sua mente. Só a letra — sem o nome. Depois olha os comentários abaixo. Se a mesma letra aparecer várias vezes, não é coincidência.", "cta_venda": "Comenta INICIAL aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'S — Antes e Depois', '@gstalves', 'Instagram', 'Transformação', 'Contraste emocional + identificação', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','transformação']::text[], '{"gancho": "Antes: sozinha, atraindo os homens errados, sem entender por quê. Depois: ela encontrou o que estava bloqueando tudo.", "participacao_ativa": "Toca no coração se você se identifica com o ''antes''.", "narrativa": "A Julia tinha 34 anos e um padrão que não mudava. Homens intensos no começo, distantes depois. Ela tentou de tudo — terapia, app de relacionamento, mudar o jeito de agir. Nada funcionava. Quando ela fez o teste, a leitura mostrou exatamente qual bloqueio na frequência dela estava atraindo esse perfil. Em menos de 3 semanas do ajuste, ela conheceu o Marco — alguém completamente diferente de todos que tinham aparecido antes. Presente, estável, apaixonado.", "reframe": "Não era ela. Era a frequência. E quando isso muda, tudo muda — inclusive o rosto de quem aparece na sua vida.", "cta_engajamento": "Comenta DEPOIS aqui embaixo se você está pronta para essa mudança. Cada comentário é uma intenção declarada — e o universo responde para quem declara.", "cta_venda": "Comenta DEPOIS aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'T — Data do Encontro', '@gstalves', 'Instagram', 'Revelação com timeline', 'Especificidade + antecipação', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','revelação com timeline']::text[], '{"gancho": "Existe uma data específica em que você e sua alma gêmea vão se cruzar. E ela está mais perto do que você imagina.", "participacao_ativa": "Toca no coração se você quer saber quando vai ser.", "narrativa": "Essa data não é aleatória. Ela está escrita no seu mapa astral desde o dia em que você nasceu — junto com as circunstâncias do encontro e as características de quem vai aparecer. A leitura astral consegue identificar essa janela de tempo com base na sua data de nascimento. E não só a data — o rosto da pessoa, a energia que vai existir entre vocês, e o que pode estar atrasando esse encontro agora.", "reframe": "Você não precisa esperar sem saber. O teste mostra o que está escrito para você — e o que, se ajustado agora, acelera tudo.", "cta_engajamento": "Curte esse vídeo e comenta o mês em que você nasceu aqui embaixo. Vou revelar nos comentários o que o universo preparou para o seu mês — e quando a janela do encontro está mais aberta.", "cta_venda": "Comenta QUANDO aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb),
('bded734b-15c0-4db3-851b-5ad763ee33c8'::uuid, 'U — Ele Nunca Te Esqueceu', '@gstalves', 'Instagram', 'Retorno emocional', 'Saudade ativa + esperança', 'soulmate / cartomante astral', ARRAY['soulmate-test','astral','mvmcreators','retorno emocional']::text[], '{"gancho": "Tem um homem que nunca te esqueceu — mesmo depois de anos, mesmo estando longe.", "participacao_ativa": "Toca no coração se tem alguém assim na sua vida.", "narrativa": "Ele pode ter seguido em frente na aparência. Mas nas noites quietas, o pensamento volta. Ele se pergunta como você está. Olha o perfil às vezes. Segura o celular. Existe uma conexão de frequência entre vocês que não se desfaz com o tempo — porque almas gêmeas não somem, elas ficam em suspensão. Esperando o momento certo para o alinhamento acontecer.", "reframe": "O teste revela se esse homem é de fato a sua alma gêmea — ou se existe alguém com uma frequência ainda mais forte esperando para entrar na sua vida.", "cta_engajamento": "Manda esse vídeo para ele. Sem texto. Sem explicação. Só manda. Observa o que acontece nas próximas 48 horas. O universo não precisa de palavras para agir.", "cta_venda": "Comenta VOLTA aqui embaixo e eu te mando agora. Ou clica no meu perfil e acessa o link na bio. Ou veja o primeiro comentário aqui embaixo. O teste é gratuito porque essa mensagem foi feita para você. Vai lá fazer. E volta aqui para me agradecer."}'::jsonb);